    while d * d <= nn:
        cnt = 0
        while nn % d == 0:
            nn //= d
            cnt += 1
        if cnt > 0:
            pf[d] = cnt
        d = 3 if d == 2 else d + 2
    if nn > 1:
        pf[nn] = pf.get(nn, 0) + 1
    return pf  # dict p -> exponent

def count_coprime_upto(N, primes):
    # Inclusion-exclusion over prime set
    if N <= 0:
        return 0
    P = list(primes)
    res = 0
    # subsets via recursion
    def dfs(i, prod, sign):
        nonlocal res
        if i == len(P):
            res += sign * (N // prod)
            return
        # include P[i]
        dfs(i + 1, prod * P[i], -sign)
        # exclude P[i]
        dfs(i + 1, prod, sign)
    dfs(0, 1, 1)
    return res

def vp_factorial(m, p):
    s = 0
    while m:
        m //= p
        s += m
    return s

